// Three of the pack's gotchas now have structural checks (via the minimal YAML
// parser); the jsdom-style runtime ones stay prose in RULES.md.
export default {
  id: 'aws-sam',
  ruleRoutingGuidance: {
    belongs: 'serverless AWS stacks: SAM template shape, Lambda handler paths, esbuild bundling, API Gateway and CloudFront gotchas',
    excludes: 'backend Google ID token validation — google-identity; generic Node packaging habits — node',
  },
  badge: 'badge.svg',
  marker: 'a SAM template (template.yaml/.yml)',
  detect: (ctx) => ctx.tracked.includes('template.yaml') || ctx.tracked.includes('template.yml'),
  prose: 'RULES.md',
  worldRules: [esbuildDependency, handlerPath, cloudfrontAuthorization],
};

[Resource from github at repo://missingbulb/claudinite/sha/b56a15caf26234181de17a90913adb687096f973/contents/packs/basics/scheduler-workflow-shape.mjs] import { finding } from '../../engine/checks/helpers/findings.mjs';

// The vendored per-repo scheduler workflow (per-project-scheduling DESIGN §3) is
// a shape-enforced thin shim: hourly cron on a repo-hashed minute constrained to
// :10–:50, a concurrency group, a workflow_dispatch trigger, and a call into the
// vendored engine entry. This asserts that shape wherever the file exists.
//
// RELEVANCE FIRST (engine/checks/README.md): a skill/pack check runs on every
// repo, so gate on the artifact — here, the scheduler workflow file existing.
// Inert until a repo vendors it (its cutover); a repo without one is untouched.
const SCHEDULER_WORKFLOW = '.github/workflows/claudinite-scheduler.yml';

const rule = {
  id: 'scheduler-workflow-shape',
  severity: 'blocking',
  description: 'The vendored claudinite-scheduler.yml is a thin shim: hourly :10–:50 cron, concurrency, workflow_dispatch, calls the engine',
  doc: 'packs/basics/scheduled-tasks.md',
  why: 'the scheduler is the repo\'s only cron and its slot math anchors on the hour — a cron off the :10–:50 band, or a missing concurrency/dispatch guard, silently breaks staggering, double-run safety, or manual runs',

  run(ctx) {
    if (!ctx.files.includes(SCHEDULER_WORKFLOW)) return [];
    const text = ctx.read(SCHEDULER_WORKFLOW);
    if (text === null) return [];
    const out = [];
    const flag = (what, fix) => out.push(finding(rule, { file: SCHEDULER_WORKFLOW, what, fix }));

    // Exactly one hourly cron whose minute is a single integer in [10, 50].
    const crons = [...text.matchAll(/cron:\s*['"]?([^'"\n]+?)['"]?\s*$/gm)].map((m) => m[1].trim());
    if (crons.length !== 1) {
      flag(`declares ${crons.length} cron schedules, expected exactly one`, 'keep a single hourly cron — the scheduler is the repo\'s only cron');
    }
    for (const cron of crons) {
      const parts = cron.split(/\s+/);
      const minute = Number(parts[0]);
      const hourly = parts.length === 5 && parts.slice(1).join(' ') === '* * * *';
      if (!hourly) {
        flag(`cron "${cron}" is not an hourly schedule`, 'use "<minute> * * * *" — hourly, so the run-ledger due-slot math catches every slot');
      }
      if (!(Number.isInteger(minute) && minute >= 10 && minute <= 50)) {
        flag(`cron minute "${parts[0]}" is not a single integer in :10–:50`, 'set a fixed minute between 10 and 50 (bootstrap assigns the repo-hashed value) — off-band crons collide with GitHub\'s :00 stampede or the hour boundary the slot math anchors on');
      }
    }
    if (!/^\s*workflow_dispatch:/m.test(text)) {
      flag('has no workflow_dispatch trigger', 'add workflow_dispatch: so the scheduler can be run manually');
    }
    if (!/^\s*concurrency:/m.test(text)) {
      flag('has no concurrency group', 'add a concurrency: group so overlapping runs serialize (double-run safety)');
    }
    if (!/engine\/scheduler\/run\.mjs/.test(text)) {
      flag('does not run the vendored engine entry', 'the job must run node .claudinite/shared/engine/scheduler/run.mjs — all logic lives in the vendored engine, not the workflow');
    }
    // Baselining runs as this workflow's `agent_preprocessing` and its `deliver()`
    // pushes the per-cycle maintenance branch and opens/auto-merges its PR via the
    // Action GITHUB_TOKEN (agent-preprocessing §7/E4). An explicit `permissions:`
    // block caps the token, so the scheduler MUST grant these writes or the
    // self-refresh 403s — an easy-to-miss regression the read-only original had.
    if (!/^\s*contents:\s*write\b/m.test(text)) {
      flag('does not grant contents: write', "set permissions.contents: write — baselining's deliver() pushes the maintenance branch; without it the self-refresh 403s");
    }
    if (!/^\s*pull-requests:\s*write\b/m.test(text)) {
      flag('does not grant pull-requests: write', "set permissions.pull-requests: write — baselining's deliver() opens the maintenance PR and arms auto-merge; without it the PR create 403s");
    }
    return out;
  },
};

export default rule;

{"number":335,"title":"The vendored-mount flip strands member-authored docs describing the legacy mount; phase 3 needs a reference sweep","body":"From a design review of `mount/DESIGN.md` (#315).

**Problem 1 — member docs.** The flip converts wiring, but nothing sweeps member *prose*. GoogleCalendarEventCreator&#39;s `CLAUDE.md`, `dev/procedures/github.md`, and `dev/procedures/technicalGotchas.md` document Method B extensively — the tarball sync, the git-proxy rationale (#364 there), and the stale-mount gotcha whose remedy is &#34;re-run `.claude/hooks/sync-claudinite.sh` by hand&#34;. The morning after the flip, all of it describes a mount that no longer exists, and the re-run-the-sync-hook advice is **actively wrong guidance an agent may follow**. Pair the flip (or a follow-up note) with a per-member doc-reconciliation pass — or at minimum extend the flip&#39;s member issue to enumerate the stale docs for an attended session to fix.

**Problem 2 — phase 3 blast radius.** The chrome-release-vendoring incident (retirement stranded inline tolerances, canon main red, reverted — fixed by PR-gating deletions in #313) taught: the probe&#39;s surface must be reviewed against the deletion&#39;s blast radius. Phase 3 deletes the canon sync hook, bootstrap&#39;s transition appendix, and the worker&#39;s legacy branch. Before that lands: sweep for *references* to the retired plumbing (member docs included; out-of-repo Setup scripts are covered by the flip&#39;s re-paste issue), and land the deletion through the `claudinite/retire-migrations` PR gate so canon CI proves reference-safety.","state":"open","html_url":"https://github.com/[REDACTED:env:CCR_TRIGGER_REPO]/issues/335","user":{"login":"missingbulb","id":73882448,"profile_url":"https://github.com/missingbulb","avatar_url":"https://avatars.githubusercontent.com/u/73882448?v=4"},"author_association":"OWNER","reactions":{"total_count":0,"+1":0,"-1":0,"laugh":0,"confused":0,"heart":0,"hooray":0,"rocket":0,"eyes":0},"created_at":"2026-07-18T19:50:01Z","updated_at":"2026-07-18T19:50:01Z","has_parent":false,"has_children":false}

